{
  "case_id": "xsu_sg_001_general_conditions",
  "criteria": {
    "c01_overall_legal_correctness": {
      "label": "met",
      "reason": "Svaret gengiver de tre betingelser korrekt: almindelige SU-/slutlånsbetingelser, videregående uddannelse eller dansk EUD, og varig fysisk/psykisk funktionsnedsættelse med meget betydelige begrænsninger i erhvervsevnen. Det indeholder ingen væsentlige juridiske fejl. Den afsluttende sætning om ret til SU og indskrivning svarer til vejledningens afsnit 3.2.1."
    },
    "c02_required_elements_complete": {
      "label": "not_met",
      "reason": "De tre betingelsesled er med. Det første kritiske element kræver dog også, at handicaptillægget udbetales sammen med SU-stipendium eller slutlån. Det fremgår ikke. Svaret siger kun, at man skal opfylde de almindelige SU-betingelser og have ret til SU. Svaret nævner heller ikke, at det er et tillæg. Det betyder, at et kritisk element mangler."
    },
    "c03_direct_relevance": {
      "label": "met",
      "reason": "Svaret er en direkte opremsning af betingelserne for handicaptillæg, som spørgsmålet beder om. Der er ingen irrelevant tekst."
    },
    "c04_source_traceability": {
      "label": "not_met",
      "reason": "Svaret angiver ingen identificerbar kilde, hverken lov, bekendtgørelse eller vejledning."
    },
    "c05_source_validity": {
      "label": "not_assessable",
      "reason": "Der er ikke angivet nogen kilde, så gyldigheden kan ikke vurderes."
    },
    "c06_claim_source_support": {
      "label": "not_assessable",
      "reason": "Der er ikke angivet nogen kilde, så støtten til påstandene kan ikke vurderes."
    },
    "c07_no_unsupported_legal_additions": {
      "label": "met",
      "reason": "Alle udsagn kan genfindes i vejledningens afsnit 3.1, 3.2.1 og 3.3 samt i SU-lovens § 7, stk. 3. Svaret tilføjer ingen ubegrundede regler, tærskler eller undtagelser."
    },
    "c08_qualifications_and_exceptions": {
      "label": "met",
      "reason": "Rubrikken kræver kun, at svaret er et overblik, og ikke en særskilt standardadvarsel. Det er opfyldt. Svaret fremstiller betingelserne som et overblik uden at gøre dem mere absolutte end kilden. De væsentlige kvalifikationer 'varig' og 'meget betydelige' er bevaret."
    },
    "c09_reasoning_coherence": {
      "label": "met",
      "reason": "Opremsningen er sammenhængende. Den afsluttende sætning om ret til SU og indskrivning gentager og uddyber punkt 1 uden at modsige noget."
    },
    "c10_legal_modality_precision": {
      "label": "met",
      "reason": "'Skal' gengiver korrekt, at betingelserne er forudsætninger, jf. vejledningens afsnit 3.1 og 3.2.1. Der er ikke gjort skøn eller undtagelser absolutte."
    }
  },
  "xhaile_coverage": {
    "A1": {
      "label": "yes",
      "reason": "Punkt 1 angiver, at de almindelige betingelser for SU eller slutlån skal opfyldes."
    },
    "A2": {
      "label": "partial",
      "reason": "Svaret nævner videregående uddannelse eller dansk EUD. Det nævner ikke EUX eller, at erhvervslignende uddannelse i udlandet ikke er omfattet."
    },
    "A3": {
      "label": "yes",
      "reason": "Svaret gengiver betingelsen om varig fysisk eller psykisk funktionsnedsættelse med meget betydelige begrænsninger i evnen til erhvervsarbejde næsten ordret."
    },
    "A4": {
      "label": "yes",
      "reason": "Svaret siger, at den uddannelsessøgende skal have ret til SU og være indskrevet på og gennemgå en uddannelse, der berettiger til SU eller slutlån."
    },
    "A6": {
      "label": "no",
      "reason": "Svaret nævner ikke, at danske erhvervsuddannelser omfatter EUX, eller at udenlandske erhvervslignende uddannelser er udelukket. Det angiver kun EUD generelt."
    }
  },
  "overall_notes": "Svaret er indholdsmæssigt korrekt og dækker de tre centrale betingelsesled. Det mangler dog, at tillægget gives sammen med SU-stipendium eller slutlån, og det angiver ingen kilder. C04 er derfor not_met, og C05 og C06 er not_assessable. De understøttende elementer om EUX og udenlandsk erhvervslignende uddannelse mangler."
}

